#include <atomic>
#include <chrono>
#include <cstdio>
#include <thread>
#include <QCoreApplication>
#include <callback/signal.h>
#include "RecordingShutdownWait.hpp"
int main(int argc, char **argv)
{
    QCoreApplication app(argc, argv);
    auto *handler = signal_handler_create();
    signal_handler_add(handler, "void stop(ptr output, int code)");
    signal_handler_add(handler, "void deactivate(ptr output)");
    std::atomic<bool> active{true};
    std::thread stopper([&] {
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
        uint8_t stack[128];
        calldata_t cd;
        calldata_init_fixed(&cd, stack, sizeof(stack));
        calldata_set_ptr(&cd, "output", nullptr);
        signal_handler_signal(handler, "deactivate", &cd);
        // Model preemption between the signal and the inactive store.
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        active = false;
    });
    bool stopped = WaitForOutputToStop(handler, 1000, [&] { return active.load(); });
    bool active_at_return = active.load();
    stopper.join();
    signal_handler_destroy(handler);
    std::printf("{\"stopped\":%s,\"active_at_return\":%s}\n", stopped ? "true" : "false", active_at_return ? "true" : "false");
    return stopped && active_at_return ? 1 : 0;
}
